"""Build a local HTML review of existing PNGs. Does not edit image pixels."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ROWS = []
for key, name in [("sister", "Sister Elian"), ("mara", "Mara"), ("osric", "Osric"), ("rook", "Captain Rook")]:
    ROWS.append(f'''<section><h2>{name}</h2><div class="pair"><figure><img src="blink-work/{key}-before.png"><figcaption>Legacy open frame</figcaption></figure><figure><img class="animated" data-open="../assets/old-masters/npc-{key}.png" data-closed="../assets/old-masters/npc-{key}-blink.png" src="../assets/old-masters/npc-{key}.png"><figcaption>Approved master / eye-only blink</figcaption></figure><figure><img class="animated face" data-open="blink-work/{key}-open-face.png" data-closed="blink-work/{key}-game-blink-face.png" src="blink-work/{key}-open-face.png"><figcaption>Actual composited eyelids, enlarged</figcaption></figure></div></section>''')

HTML = '''<!doctype html><html lang="en"><meta charset="utf-8"><title>The Last Roads / NPC art review</title>
<style>:root{color-scheme:dark;--mat:#1b292c}body{background:#0c191c;color:#e4d7b8;font:17px/1.6 system-ui;margin:32px auto;max-width:1150px;padding:0 20px}h1,h2{font-family:Georgia,serif;font-weight:400}button,select{font:inherit;padding:8px 14px;background:#253d3e;color:inherit;border:1px solid #89754b;margin-right:10px}.pair{display:grid;grid-template-columns:1fr 1fr 1fr;gap:15px}figure{margin:0;background:var(--mat);text-align:center;padding:12px}figure img{height:450px;max-width:100%;object-fit:contain}.face{height:220px!important;width:220px}figcaption{font-size:14px}section{border-top:1px solid #46504a;margin-top:30px;padding-top:15px}.world{width:100%;border:1px solid #82724f}small{color:#aeb7a2}nav{position:sticky;top:0;background:#0c191cf2;padding:12px 0;z-index:1}</style>
<h1>The Last Roads / Old Masters production review</h1>
<p>Four lookbook characters. The blink changes only two small eyelid masks; body, props, mouth, silhouette, baseline and alpha remain identical. Originals are retained. Choose a matte to inspect edges.</p>
<nav><button onclick="mat('#d6dedf')">Light matte</button><button onclick="mat('#121b20')">Dark matte</button><button onclick="mat('#267aab')">Saturated matte</button><label><input id="play" type="checkbox" checked> Animate blinks</label></nav>
__ROWS__
<section><h2>Actual world scale / every supported colour look</h2><p>Sister, Mara, Osric and Rook together in the inn yard. Choose daylight or night; game text and gameplay are unchanged by the visual preset.</p>
<select id="look" onchange="world()"><option value="-1">Original illustration</option><option value="0">Hollow 16</option><option value="1">Copper &amp; Pine</option><option value="2">DOS Chronicle</option><option value="3">Gothic Dusk</option><option value="4">CRT Traveller</option><option value="5">Gilded Hollow</option><option value="6">Macintosh</option><option value="7">IBM 5151</option><option value="8">Commodore 1084</option></select>
<select id="period" onchange="world()"><option value="day">Daylight</option><option value="night">Night</option></select><p><img class="world" id="cast" src="06-cast-look--1-day.png"></p></section>
<section><h2>Technical records</h2><p><a href="../assets/old-masters/blink-audit.json">Blink mask comparison</a> / <a href="../assets/old-masters/alpha-audit.json">Alpha and original-hash audit</a> / <a href="../assets/old-masters/asset-map.json">Asset mapping</a> / <a href="../game_production.md">Production document</a></p><small>Images were generated with built-in image_gen; crop, atlas and mask assembly use Godot. This page only displays the resulting files. Screen colour treatments are not separately authored pixel-art assets.</small></section>
<script>function mat(c){document.documentElement.style.setProperty('--mat',c)}function frame(closed){document.querySelectorAll('.animated').forEach(i=>{i.src=closed?i.dataset.closed:i.dataset.open})}setInterval(()=>{if(document.getElementById('play').checked){frame(true);setTimeout(()=>frame(false),160)}else{frame(false)}},2400);function world(){document.getElementById('cast').src='06-cast-look-'+document.getElementById('look').value+'-'+document.getElementById('period').value+'.png'}</script></html>'''
(ROOT / "reports/npc-blink-check.html").write_text(HTML.replace("__ROWS__", "".join(ROWS)), encoding="utf-8")
print("ART REVIEW READY: reports/npc-blink-check.html")
